package com.primehr.operations.application;

import com.primehr.evidence.application.*;import com.primehr.evidence.domain.EvidenceArtifact;import com.primehr.evidence.infrastructure.EvidenceArtifactRepository;import com.primehr.operations.api.OperationsDtos.*;import com.primehr.operations.domain.*;import com.primehr.operations.infrastructure.*;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;

@Service @Transactional
public class OperationsServiceImpl implements OperationsService {
 private final ReconciliationRunRepository runs;private final ReconciliationFindingRepository findings;private final RetentionPolicyVersionRepository policies;private final LegalHoldRepository holds;private final EvidenceArtifactRepository artifacts;private final StoredDocumentCatalog documents;private final EvidenceLiveSourceVerifier verifier;private final DocumentStorage storage;private final PrimeHrAuditService audit;private final OperationsObservability observability;
 public OperationsServiceImpl(ReconciliationRunRepository r,ReconciliationFindingRepository f,RetentionPolicyVersionRepository p,LegalHoldRepository h,EvidenceArtifactRepository a,StoredDocumentCatalog d,EvidenceLiveSourceVerifier v,DocumentStorage s,PrimeHrAuditService au,OperationsObservability o){runs=r;findings=f;policies=p;holds=h;artifacts=a;documents=d;verifier=v;storage=s;audit=au;observability=o;}
 @Override public RunResponse run(String agency,String token,String actor,String correlation,boolean scheduled){Instant started=Instant.now();String trigger=scheduled?"SCHEDULED":"MANUAL";try{var run=runs.saveAndFlush(new ReconciliationRun(agency,scheduled?ReconciliationRun.TriggerType.SCHEDULED:ReconciliationRun.TriggerType.MANUAL,actor,started));int checked=0;int count=0;for(var artifact:artifacts.findByAgencyIdOrderByAddedAtAsc(agency)){if(artifact.getKind()!=EvidenceArtifact.Kind.LIVE_SOURCE)continue;checked++;var finding=sourceFinding(agency,run.getId(),artifact,token,actor,correlation);if(finding!=null){findings.save(finding);count++;}}for(var document:documents.documents(agency)){checked++;var finding=storageFinding(agency,run.getId(),document);if(finding!=null){findings.save(finding);count++;}}run.complete(checked,count,Instant.now());runs.saveAndFlush(run);var out=response(run);audit.record(agency,"RUN_READ_ONLY_RECONCILIATION","PRIMEHR_RECONCILIATION_RUN",run.getId(),null,run.getVersion(),null,out,scheduled?"Scheduled read-only reconciliation":"Manual read-only reconciliation",correlation);observability.reconciliation(trigger,out.status(),checked,count,Duration.between(started,Instant.now()));return out;}catch(RuntimeException exception){observability.reconciliation(trigger,"FAILED",0,0,Duration.between(started,Instant.now()));throw exception;}}
 private ReconciliationFinding sourceFinding(String agency,String run,EvidenceArtifact a,String token,String actor,String correlation){try{var observed=verifier.verify(agency,new EvidenceLiveSourceVerifier.Request(a.getSourceType(),a.getSourceId(),a.getSourceVersion(),a.getSourceFingerprint(),a.getSourceChangedAt()),token,actor,correlation);if(observed.sourceVersion()!=a.getSourceVersion()||!observed.sourceFingerprint().equals(a.getSourceFingerprint()))return finding(agency,run,ReconciliationFinding.Kind.SOURCE_DRIFT,a,observed.sourceVersion(),observed.sourceFingerprint(),"Authoritative source differs from the immutable snapshot");return null;}catch(ResourceNotFoundException e){return finding(agency,run,ReconciliationFinding.Kind.SOURCE_MISSING,a,null,null,"Authoritative source is no longer available");}catch(OptimisticConflictException e){return finding(agency,run,ReconciliationFinding.Kind.SOURCE_DRIFT,a,null,null,"Authoritative source version or fingerprint changed");}catch(RuntimeException e){return finding(agency,run,ReconciliationFinding.Kind.SOURCE_UNAVAILABLE,a,null,null,"Authoritative source could not be checked");}}
 private ReconciliationFinding storageFinding(String agency,String run,StoredDocumentCatalog.DocumentReference d){try{var metadata=storage.metadata(d.objectKey());if(!metadata.exists())return storageFinding(agency,run,ReconciliationFinding.Kind.STORAGE_MISSING,d,"Stored object metadata was not found");if(!Objects.equals(d.byteSize(),metadata.byteSize()))return storageFinding(agency,run,ReconciliationFinding.Kind.STORAGE_SIZE_MISMATCH,d,"Stored object size differs from recorded metadata");return null;}catch(RuntimeException e){return storageFinding(agency,run,ReconciliationFinding.Kind.STORAGE_UNAVAILABLE,d,"Storage metadata could not be checked");}}
 private static ReconciliationFinding storageFinding(String agency,String run,ReconciliationFinding.Kind kind,StoredDocumentCatalog.DocumentReference d,String summary){return new ReconciliationFinding(agency,run,kind,d.recordType(),d.recordId(),null,null,null,null,null,summary);}
 private static ReconciliationFinding finding(String agency,String run,ReconciliationFinding.Kind kind,EvidenceArtifact a,Long version,String fingerprint,String summary){return new ReconciliationFinding(agency,run,kind,"EVIDENCE_ARTIFACT",a.getId(),a.getSourceId(),a.getSourceVersion(),a.getSourceFingerprint(),version,fingerprint,summary);}
 @Override @Transactional(readOnly=true)public List<RunResponse>runs(String agency){return runs.findByAgencyIdOrderByStartedAtDesc(agency).stream().map(this::response).toList();}
 @Override public FindingResponse acknowledge(String agency,String id,long version,String note,String actor,String correlation){var f=finding(agency,id,version);var before=findingResponse(f);f.acknowledge(actor,Instant.now());findings.saveAndFlush(f);var out=findingResponse(f);audit.record(agency,"ACKNOWLEDGE_RECONCILIATION_FINDING","PRIMEHR_RECONCILIATION_FINDING",id,null,f.getVersion(),before,out,note,correlation);return out;}
 @Override public FindingResponse resolve(String agency,String id,long version,String note,String actor,String correlation){var f=finding(agency,id,version);var before=findingResponse(f);f.resolve(actor,note,Instant.now());findings.saveAndFlush(f);var out=findingResponse(f);audit.record(agency,"RESOLVE_RECONCILIATION_FINDING","PRIMEHR_RECONCILIATION_FINDING",id,null,f.getVersion(),before,out,note,correlation);return out;}
 private ReconciliationFinding finding(String agency,String id,long version){var f=findings.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Reconciliation finding not found"));if(f.getVersion()!=version)throw new OptimisticConflictException("Reconciliation finding changed; reload it");return f;}
 @Override public PolicyResponse createPolicy(String agency,PolicyInput i,String correlation){String code=i.code().trim().toUpperCase();if(policies.existsByAgencyIdAndCodeAndPolicyVersion(agency,code,i.policyVersion()))throw new OptimisticConflictException("Retention policy version already exists");var p=policies.saveAndFlush(new RetentionPolicyVersion(agency,code,i.policyVersion(),i.retentionTag(),i.retentionDays(),i.effectiveFrom(),i.effectiveTo(),i.basis(),i.published()));var out=policy(p);audit.record(agency,"CREATE_RETENTION_POLICY_VERSION","PRIMEHR_RETENTION_POLICY",p.getId(),p.getPolicyVersion(),p.getVersion(),null,out,i.basis(),correlation);return out;}
 @Override @Transactional(readOnly=true)public List<PolicyResponse>policies(String agency){return policies.findByAgencyIdOrderByCodeAscPolicyVersionDesc(agency).stream().map(this::policy).toList();}
 @Override public HoldResponse placeHold(String agency,HoldInput i,String actor,String correlation){if(holds.existsByAgencyIdAndRecordTypeAndRecordIdAndActiveTrue(agency,i.recordType(),i.recordId()))throw new OptimisticConflictException("An active legal hold already exists for this record");var h=holds.saveAndFlush(new LegalHold(agency,i.recordType(),i.recordId(),i.reason(),i.referenceNo(),actor,Instant.now()));var out=hold(h);audit.record(agency,"PLACE_LEGAL_HOLD","PRIMEHR_LEGAL_HOLD",h.getId(),null,h.getVersion(),null,out,i.reason(),correlation);return out;}
 @Override public HoldResponse releaseHold(String agency,String id,long version,String reason,String actor,String correlation){var h=holds.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Legal hold not found"));if(h.getVersion()!=version)throw new OptimisticConflictException("Legal hold changed; reload it");var before=hold(h);h.release(actor,reason,Instant.now());holds.saveAndFlush(h);var out=hold(h);audit.record(agency,"RELEASE_LEGAL_HOLD","PRIMEHR_LEGAL_HOLD",id,null,h.getVersion(),before,out,reason,correlation);return out;}
 @Override @Transactional(readOnly=true)public List<HoldResponse>holds(String agency){return holds.findByAgencyIdOrderByPlacedAtDesc(agency).stream().map(this::hold).toList();}
 @Override @Transactional(readOnly=true)public List<RetentionEligibility>retentionReport(String agency,LocalDate asOf){var ps=policies.findByAgencyIdOrderByCodeAscPolicyVersionDesc(agency);return documents.retentionRecords(agency).stream().map(a->{var p=ps.stream().filter(x->x.getRetentionTag().equalsIgnoreCase(a.retentionTag())&&x.effectiveOn(a.recordDate())).max(Comparator.comparingInt(RetentionPolicyVersion::getPolicyVersion));boolean legal=holds.existsByAgencyIdAndRecordTypeAndRecordIdAndActiveTrue(agency,a.recordType(),a.recordId());LocalDate eligibleOn=p.map(x->a.recordDate().plusDays(x.getRetentionDays())).orElse(null);boolean eligible=p.isPresent()&&!legal&&!asOf.isBefore(eligibleOn);String explanation=p.isEmpty()?"No published policy applies":legal?"Active legal hold":"Eligible on "+eligibleOn;return new RetentionEligibility(a.recordType(),a.recordId(),a.retentionTag(),a.recordDate(),eligibleOn,p.isPresent(),legal,eligible,explanation);}).toList();}
 private RunResponse response(ReconciliationRun r){return new RunResponse(r.getId(),r.getTriggerType().name(),r.getStatus().name(),r.getStartedBy(),r.getStartedAt(),r.getCompletedAt(),r.getCheckedCount(),r.getFindingCount(),r.getFailureSummary(),r.getVersion(),findings.findByAgencyIdAndRunIdOrderByCreatedAtAsc(r.getAgencyId(),r.getId()).stream().map(this::findingResponse).toList());}
 private FindingResponse findingResponse(ReconciliationFinding f){return new FindingResponse(f.getId(),f.getRunId(),f.getKind().name(),f.getStatus().name(),f.getRecordType(),f.getRecordId(),f.getSourceId(),f.getStoredVersion(),f.getStoredFingerprint(),f.getObservedVersion(),f.getObservedFingerprint(),f.getSummary(),f.getAcknowledgedBy(),f.getAcknowledgedAt(),f.getResolvedBy(),f.getResolvedAt(),f.getResolutionNote(),f.getVersion());}
 private PolicyResponse policy(RetentionPolicyVersion p){return new PolicyResponse(p.getId(),p.getCode(),p.getPolicyVersion(),p.getRetentionTag(),p.getRetentionDays(),p.getEffectiveFrom(),p.getEffectiveTo(),p.getBasis(),p.isPublished(),p.getVersion());}
 private HoldResponse hold(LegalHold h){return new HoldResponse(h.getId(),h.getRecordType(),h.getRecordId(),h.getReason(),h.getReferenceNo(),h.getPlacedBy(),h.getPlacedAt(),h.isActive(),h.getReleasedBy(),h.getReleasedAt(),h.getReleaseReason(),h.getVersion());}
}
